const img=document.querySelector('#scene'),svg=document.querySelector('#boxes'),caption=document.querySelector('#frame-caption'),toggle=document.querySelector('#annotations'),labels=document.querySelector('#box-labels'),selector=document.querySelector('#case-select'),summary=document.querySelector('#case-summary');
const colors={ground_truth:'#d8ee8c',matched:'#78d4a2',false_alarm:'#ffb268',ignored:'#b1bac2'};
let data=null,active=0,mode='ground_truth';
function node(tag,attrs){const el=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [key,value] of Object.entries(attrs))el.setAttribute(key,value);return el}
function render(){if(!data)return;const c=data.cases[active];img.src='assets/'+c.file;img.alt=`Validation case ${active+1}: ${c.reason}`;svg.setAttribute('viewBox',`0 0 ${c.width} ${c.height}`);svg.replaceChildren();
for(const [x,y,w,h] of c.ignore_regions)svg.append(node('rect',{x,y,width:w,height:h,fill:'none',stroke:'#b1bac2','stroke-width':1,'stroke-dasharray':'5 4','vector-effect':'non-scaling-stroke'}));
const boxes=mode==='ground_truth'?c.ground_truth:c[mode].predictions;
for(const p of boxes){const [x,y,w,h]=p.bbox,color=colors[p.status];const name=data.categories[p.category_id-1]+(p.score===undefined?'':` ${(100*p.score).toFixed(0)}%`);const group=node('g',{});const rect=node('rect',{x,y,width:w,height:h,fill:'none',stroke:color,'stroke-width':1.8,'vector-effect':'non-scaling-stroke'});const title=node('title',{});title.textContent=`${name} · ${p.status.replace('_',' ')}`;rect.append(title);group.append(rect);
if(labels.checked){const text=node('text',{x:Math.max(0,x),y:Math.max(14,y-4),'font-size':Math.max(15,c.width/75),fill:color,stroke:'#19251f','stroke-width':2,'paint-order':'stroke','font-family':'sans-serif'});text.textContent=name;group.append(text)}svg.append(group)}
svg.style.display=toggle.checked?'block':'none';caption.textContent=`CASE ${String(active+1).padStart(2,'0')} / ${c.file} / ${c.width} × ${c.height}px`;
summary.replaceChildren();const heading=document.createElement('h3');heading.textContent=c.reason;const note=document.createElement('p');note.textContent=c.visual_note+' '+c.note;summary.append(heading,note);const counts=document.createElement('p');counts.className='current-counts';counts.textContent=mode==='ground_truth'?`${c.ground_truth.length} scored shared-class objects. Dashed gray boxes mark non-scored regions.`:`${mode==='baseline'?'Pretrained':'Fine-tuned'}: ${c[mode].tp} matched · ${c[mode].fp} false alarms · ${c[mode].fn} missed · ${c[mode].ignored} ignored`;summary.append(counts);
selector.value=String(active);document.querySelectorAll('[data-scene]').forEach(b=>{const selected=+b.dataset.scene===active;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))});document.querySelectorAll('[data-mode]').forEach(b=>{const selected=b.dataset.mode===mode;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))})}
for(const control of [toggle,labels])control.addEventListener('change',render);
selector.addEventListener('change',()=>{active=+selector.value;render()});document.querySelectorAll('[data-scene]').forEach(b=>b.addEventListener('click',()=>{active=+b.dataset.scene;render()}));document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;render()}));
fetch('gallery.json').then(r=>{if(!r.ok)throw Error('Gallery unavailable');return r.json()}).then(d=>{data=d;selector.replaceChildren();d.cases.forEach((c,i)=>{const option=document.createElement('option');option.value=i;option.textContent=`${String(i+1).padStart(2,'0')} · ${c.reason}`;selector.append(option)});render()}).catch(()=>{caption.textContent='Comparison data unavailable. Please reload the page.';document.querySelectorAll('.imagery button,.imagery select,.imagery input').forEach(e=>e.disabled=true)});
